        ['type' => 'quote', 'data' => [
            'text_en' => 'This is the figure of the Mazda-worshipping Lord Shapur, king of kings of Iran and non-Iran, whose race is from the gods.',
            'text_ku' => 'ئەمە وێنەی خاوەنشکۆ شاپووری مەزداپەرستە، شاهانشای ئێران و ئەنێران، کە ڕەچەڵەکی لە خوداوەندانەوەیە.',
            'text_ar' => 'هذه صورة السيد شابور عابد مزدا، ملك ملوك إيران وغير إيران، الذي نسبه من الآلهة.',
            'source_en' => 'The Pahlavi inscription of Shapur II in the small iwan', 'source_ku' => 'نووسینی پەهلەویی شاپووری دووەم لە ئەیوانە بچووکەکەدا', 'source_ar' => 'نقش شابور الثاني البهلوي في الإيوان الصغير',
        ]],

        ['type' => 'facts', 'data' => [
            'layout' => 'cards',
            'items' => [
                ['text_en' => 'The hunting walls are the most detailed picture of Sasanian court life that survives: boats, elephants, camels, musicians, beaters, and the king in several moments of one day.', 'text_ku' => 'دیوارەکانی ڕاو وردترین وێنەی ژیانی دیوانی ساسانین کە ماونەتەوە: بەلەم، فیل، وشتر، مۆسیقاژەن، نێچیرڕاون، و پاشا لە چەند ساتێکی یەک ڕۆژدا.', 'text_ar' => 'جدران الصيد أدقّ صورة باقية لحياة البلاط الساساني: قوارب وفيلة وجمال وموسيقيون وطاردون، والملك في لحظات عدة من يوم واحد.'],
                ['text_en' => 'The knight\'s recurve bow is of a type scholars call Hunnish — a weapon borrowed from the steppe enemies the Sasanians fought on their eastern frontier.', 'text_ku' => 'کەوانی پێچاوەی سوارەکە لە جۆرێکە کە زانایان پێی دەڵێن هونی — چەکێک کە لە دوژمنە دەشتاییەکانەوە وەرگیراوە کە ساسانییەکان لە سنووری ڕۆژهەڵاتیان دژیان دەجەنگان.', 'text_ar' => 'قوس الفارس المرتدّة من نوع يسمّيه الباحثون هونيّاً — سلاح مستعار من أعداء السهوب الذين قاتلهم الساسانيون على حدودهم الشرقية.'],
                ['text_en' => 'Which king the great iwan belongs to is still argued. Khosrow II is the usual answer; the crown and the style have also been read as Peroz, two centuries earlier.', 'text_ku' => 'ئەیوانە گەورەکە هی کام پاشایە هێشتا مشتومڕی لەسەرە. خوسرەوی دووەم وەڵامە باوەکەیە؛ تاج و شێوازەکەش وەک پێرۆز خوێنراونەتەوە، دوو سەدە پێشتر.', 'text_ar' => 'لا يزال الجدل قائماً حول الملك الذي يعود إليه الإيوان الكبير. خسرو الثاني هو الجواب المعتاد؛ وقُرئ التاج والأسلوب أيضاً على أنهما لبيروز، قبل قرنين.'],
                ['text_en' => 'The carvings of Mithra on a lotus and of Anahita with her jug are among the very few images of these gods made under the Sasanians themselves.', 'text_ku' => 'هەڵکەندنەکانی میترا لەسەر نیلۆفەر و ئاناهیتا بە گۆزەکەیەوە لە کەمترین وێنەکانی ئەم خوداوەندانەن کە لە سەردەمی ساسانییەکان خۆیاندا دروستکراون.', 'text_ar' => 'منحوتات ميثرا على زهرة اللوتس وأناهيتا بإبريقها من الصور النادرة جداً لهذين الإلهين التي صُنعت في عهد الساسانيين أنفسهم.'],
                ['text_en' => 'Column capitals from Bisotun and Kermanshah, carved with Sasanian kings, have been gathered in the park beside the pool — a small open-air museum of the dynasty.', 'text_ku' => 'سەرستوون لە بێستوون و کرماشانەوە، بە پاشا ساسانییەکان هەڵکەنراون، لە پارکەکەی تەنیشت حەوزەکە کۆکراونەتەوە — مۆزەخانەیەکی بچووکی کراوەی خانەدانەکە.', 'text_ar' => 'جُمعت في المتنزه بجانب البركة تيجان أعمدة من بيستون وكرمانشاه، منحوت عليها ملوك ساسانيون — متحف صغير في الهواء الطلق للسلالة.'],
                ['text_en' => 'The ornament of the arch — palmettes, acanthus, the tree of life — was copied by the builders of the first mosques; the vault itself became the iwan of every Persian mosque and madrasa.', 'text_ku' => 'ڕازاندنەوەی کەوانەکە — پاڵمێت، ئەکانسۆس، داری ژیان — لەلایەن بیناسازانی یەکەم مزگەوتەکانەوە لاسایی کرایەوە؛ گومبەزەکە خۆی بوو بە ئەیوانی هەموو مزگەوت و مەدرەسەیەکی فارسی.', 'text_ar' => 'قلّد بناة المساجد الأولى زخرف القوس — السعيفات والأقنثا وشجرة الحياة؛ وصار القبو نفسه إيوان كل مسجد ومدرسة فارسية.'],
            ],
        ]],

